import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/officeDocument/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("Archive entries:")
    for n in names:
        print("  ", n)

    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels}
    sheets = [(s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")) for s in wb.find("m:sheets", NS)]
    print("\nSheets:", sheets)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/officeDocument/2006/main}t"))
            shared.append(text)

    # styles to identify date/number formats (optional; skip)

    for sheet_name, rid in sheets:
        target = rel_map.get(rid)
        if target.startswith("/"):
            target = target[1:]
        elif not target.startswith("xl/"):
            target = "xl/" + target
        print(f"\n=== Sheet: {sheet_name} (xml={target}) ===")
        data = ET.fromstring(z.read(target))
        for row in data.find("m:sheetData", NS):
            vals = {}
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                if v is None:
                    val = None
                else:
                    raw = v.text
                    if t == "s":
                        val = shared[int(raw)]
                    elif t == "b":
                        val = raw == "1"
                    elif t == "inlineStr":
                        is_el = c.find("m:is", NS)
                        val = "".join(x.text or "" for x in is_el.iter("{http://schemas.openxmlformats.org/officeDocument/2006/main}t"))
                    else:
                        val = raw
                vals[col_to_idx(ref)] = val
            if vals:
                maxc = max(vals) + 1
                print([vals.get(i) for i in range(maxc)])

