import zipfile
import re
import xml.etree.ElementTree as ET

def local(tag):
    return tag.rsplit("}", 1)[-1]

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

with zipfile.ZipFile("budget.xlsx") as z:
    data = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

rows = {}
for row in data.iter():
    if local(row.tag) != "row":
        continue
    r = int(row.get("r"))
    cells = {}
    for c in row:
        if local(c.tag) != "c":
            continue
        t = c.get("t")
        v_el = next((x for x in c if local(x.tag) == "v"), None)
        if v_el is not None:
            val = v_el.text
        else:
            is_el = next((x for x in c if local(x.tag) == "is"), None)
            if is_el is not None:
                val = "".join(x.text or "" for x in is_el.iter() if local(x.tag) == "t")
            else:
                val = None
        cells[col_to_idx(c.get("r"))] = (t, val)
    rows[r] = cells

def get(r, col):
    return rows.get(r, {}).get(col)

expenses = []
for r in range(11, 23):
    cat = get(r, 0)[1] if get(r, 0) else None
    item = get(r, 1)[1] if get(r, 1) else None
    val = get(r, 2)[1] if get(r, 2) else None
    expenses.append((cat, item, float(val) if val is not None else None))

print(f"{'Category':<16}{'Item':<16}{'Amount':>8}")
by_cat = {}
for cat, item, val in expenses:
    print(f"{cat:<16}{item:<16}{val:>8.2f}")
    by_cat[cat] = by_cat.get(cat, 0.0) + val

print("\nTotals by category:")
total = 0.0
for cat, s in by_cat.items():
    print(f"  {cat}: {s:.2f}")
    total += s
print(f"\nTOTAL EXPENSES: {total:.2f}")

# Verify against the file's own formula
f_c23 = get(23, 2)
print(f"\nFile formula C23 (Total Expenses): {f_c23}")
print("Formula matches computed total:", f_c23 and f_c23[1] == f"{total:.0f}")

